tool_input.content:
// 把 memory-migration 提炼产物导入 OpenViking
// 关键设计：溯源信息以纯文本内嵌正文（实测元数据字段会被 VLM 丢弃，正文可保留）
import fs from "fs";
import path from "path";

const PROJECT = process.argv[2];
const DRY = process.argv.includes("--dry");
const BATCH = Number(process.argv.find((a) => a.startsWith("--batch="))?.split("=")[1] || 4);

const SRC = path.join(
  "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration\\out\\distilled-projects",
  PROJECT
);
const API = "http://127.0.0.1:1933";

// ── 读取并展平全部记忆 ──────────────────────────────
const mems = [];
for (const f of fs.readdirSync(SRC).filter((x) => x.endsWith(".json")).sort()) {
  const j = JSON.parse(fs.readFileSync(path.join(SRC, f), "utf8"));
  for (const m of j.memories || []) mems.push({ ...m, _batch: f });
}
console.log(`项目: ${PROJECT} | 记忆 ${mems.length} 条 | 每批 ${BATCH} 条`);

// ── 构造带溯源的正文 ────────────────────────────────
// 实验证明：files/sessionIds/baseline/evidence 作为元数据会被丢弃，
// 但写在正文里的纯文本会被 VLM 理解并保留下来。
function toText(m) {
  const lines = [
    `【记忆类型】${m.type}`,
    `【标题】${m.title}`,
    `【内容】${m.content}`,
  ];
  if (m.evidence) lines.push(`【验证证据】${m.evidence}`);
  if (m.files?.length) lines.push(`【涉及文件】${m.files.join(" ; ")}`);
  if (m.project) lines.push(`【所属项目】${m.project}`);
  if (m.sessionIds?.length) lines.push(`【来源会话ID】${m.sessionIds.join(", ")}`);
  if (m.baseline) lines.push(`【代码基线】${m.baseline}`);
  if (m.freshness?.lastSeen) lines.push(`【最后确认】${m.freshness.lastSeen}`);
  return lines.join("\n");
}

async function api(p, opt) {
  const r = await fetch(API + p, opt);
  const t = await r.text();
  if (!r.ok) throw new Error(`${p} → ${r.status} ${t.slice(0, 200)}`);
  return JSON.parse(t);
}

// ── 逐批导入并 commit ───────────────────────────────
const sid = `mm-${PROJECT}-${Date.now()}`.replace(/[^\w.-]/g, "_");
const batches = [];
for (let i = 0; i < mems.length; i += BATCH) batches.push(mems.slice(i, i + BATCH));

console.log(`会话: ${sid} | 批次数: ${batches.length}`);

if (DRY) {
  console.log("--- DRY RUN，前 1 条正文预览 ---");
  console.log(toText(batches[0][0]));
  process.exit(0);
}

const log = { project: PROJECT, session: sid, batches: [], startedAt: new Date().toISOString() };

for (let bi = 0; bi < batches.length; bi++) {
  const group = batches[bi];
  const msgs = group.map((m) => ({
    role: "user",
    message_kind: "user_query",
    content: toText(m),
  }));

  try {
    await api(`/api/v1/sessions/${sid}/messages/batch`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ messages: msgs }),
    });
    const c = await api(`/api/v1/sessions/${sid}/commit`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({}),
    });
    const tid = c.result?.task_id;
    log.batches.push({ i: bi, tid, count: group.length, titles: group.map((m) => m.title) });
    console.log(`[${bi + 1}/${batches.length}] 投入 ${group.length} 条 → task ${String(tid).slice(0, 8)}`);

    // 串行等待：并发 commit 会静默丢数据（已实测）
    for (let k = 0; k < 120; k++) {
      await new Promise((r) => setTimeout(r, 5000));
      const j = await api(`/api/v1/tasks/${tid}`);
      const list = Array.isArray(j) ? j : Array.isArray(j.result) ? j.result : [j.result || j];
      const t = list.find((x) => x && x.task_id === tid) || {};
      if (["completed", "failed", "error", "cancelled"].includes(t.status)) {
        const ex = t.result?.memories_extracted || {};
        console.log(`    → ${t.status} ${Math.round(t.processing_seconds || 0)}s | write:${ex.memory_write || 0} edit:${ex.memory_edit || 0} | ${t.result?.token_usage?.total?.total_tokens || 0} tokens`);
        log.batches.at(-1).result = { status: t.status, extracted: ex, secs: t.processing_seconds, tokens: t.result?.token_usage?.total?.total_tokens };
        break;
      }
    }
  } catch (e) {
    console.error(`[${bi + 1}] 失败: ${e.message}`);
    log.batches.at(-1).error = e.message;
    break; // 串行，出错即停，避免污染
  }
}

log.finishedAt = new Date().toISOString();
const logPath = path.join("C:\\Users\\ADMINI~1\\AppData\\Local\\Temp", `import-${PROJECT}.json`);
fs.writeFileSync(logPath, JSON.stringify(log, null, 1), "utf8");
console.log(`\n日志: ${logPath}`);

